// Bit-level check of app/js/mbf.js against PC-BASIC's own number classes.
// Fixture generated by test/basic/fuzz_mbf.py (see notes.md).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import * as M from '../js/mbf.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const lines = fs.readFileSync(path.join(here, 'fixtures/mbf_fuzz.jsonl'), 'utf8').trim().split('\n');
const strict = {}; // no warn handler -> soft errors throw, like the Python harness
const parse = (s) => {
  const neg = s.startsWith('-');
  let v = M.fromRepr(s.replace(/^-/, ''), false, strict);
  if (neg) v = M.neg(v, strict);
  return v;
};
const rep = (v) => ({ t: v.t, hex: M.toHex(v), str: M.toStr(v, true, false) });
const run = (f) => { try { return rep(f()); } catch (e) { return { err: e.basicError || e.message } } };
const ops = {
  add: M.add, sub: M.sub, mul: M.mul, div: M.div, pow: M.pow,
  gt: (a, b, c) => M.fromBool(M.gt(a, b, c)), eq: (a, b, c) => M.fromBool(M.eq(a, b, c)),
};
const un = {
  sin: M.sin, cos: M.cos, tan: M.tan, atn: M.atn, sqr: M.sqr, int: M.intFloor, fix: M.fix,
  cint: (a) => M.cint(a), csng: M.toSingle, cdbl: M.toDouble, abs: M.abs, neg: M.neg, exp: M.exp, log: M.log,
};
let checked = 0, bad = 0;
const fails = [];
function cmp(label, exp, got) {
  checked++;
  if (exp.err) { if (!got.err) { bad++; fails.push([label, exp, got]); } return; }
  if (got.err || exp.t !== got.t || exp.hex !== got.hex || exp.str !== got.str) { bad++; fails.push([label, exp, got]); }
}
for (const line of lines) {
  const r = JSON.parse(line);
  if (r.parseError) continue;
  const a = parse(r.a), b = parse(r.b);
  cmp(`parse ${r.a}`, r.A, rep(a));
  cmp(`parse ${r.b}`, r.B, rep(b));
  cmp(`input ${r.a}`, r.inputA, run(() => M.inputValue(r.a, '!', strict)));
  for (const [k, f] of Object.entries(ops)) cmp(`${k}(${r.a}, ${r.b})`, r.res[k], run(() => f(a, b, strict)));
  if (r.res.powi) cmp(`powi(${r.a}, ${r.powInt})`, r.res.powi, run(() => M.pow(a, M.makeInt(r.powInt), strict)));
  for (const [k, f] of Object.entries(un)) cmp(`${k}(${r.a})`, r.res[k], run(() => f(a, strict)));
}
console.log(`MBF engine vs PC-BASIC number classes: ${checked} comparisons, ${bad} mismatches`);
for (const f of fails.slice(0, 15)) console.log(JSON.stringify(f));
if (bad) process.exitCode = 1;
